mkdir -p /app/output && cat > /app/output/styles.css <<'EOF'
:root {
  --navy: #0a0a23;
  --navy-2: #14142f;
  --gold: #feac32;
  --gold-soft: #fff2d6;
  --blue: #002ead;
  --ink: #171721;
  --muted: #626677;
  --line: #e6e8ef;
  --paper: #ffffff;
  --wash: #f7f8fb;
  --green: #0f7b5f;
  --radius: 22px;
  --shadow: 0 24px 80px rgba(10, 10, 35, .10);
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: var(--wash);
  color: var(--ink);
  line-height: 1.55;
}
a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
button, input { font: inherit; }

.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: var(--navy);
  color: white;
  border-bottom: 1px solid rgba(255,255,255,.10);
}
.header-inner {
  width: min(1180px, calc(100% - 32px));
  margin: 0 auto;
  min-height: 72px;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 24px;
}
.logo {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-weight: 900;
  letter-spacing: -.03em;
  font-size: 1.25rem;
}
.logo-mark {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border: 2px solid var(--gold);
  color: var(--gold);
  font-weight: 950;
}
.search-wrap {
  position: relative;
}
.search-wrap input {
  width: 100%;
  border: 1px solid rgba(255,255,255,.20);
  background: rgba(255,255,255,.09);
  color: white;
  border-radius: 999px;
  padding: 13px 18px 13px 44px;
  outline: none;
}
.search-wrap input::placeholder { color: rgba(255,255,255,.62); }
.search-icon {
  position: absolute;
  left: 17px;
  top: 50%;
  transform: translateY(-50%);
  opacity: .65;
}
.nav-links {
  display: flex;
  gap: 8px;
  align-items: center;
}
.nav-links a, .mobile-menu a {
  padding: 10px 13px;
  border-radius: 999px;
  font-weight: 750;
  color: rgba(255,255,255,.86);
}
.nav-links a:hover, .mobile-menu a:hover { background: rgba(255,255,255,.10); color: white; }
.nav-links .donate-link, .mobile-menu .donate-link {
  background: var(--gold);
  color: var(--navy);
}
.menu-button {
  display: none;
  width: 42px;
  height: 42px;
  border: 1px solid rgba(255,255,255,.22);
  border-radius: 12px;
  background: transparent;
  color: white;
  cursor: pointer;
}
.menu-button span {
  display: block;
  width: 18px;
  height: 2px;
  background: currentColor;
  margin: 4px auto;
  transition: transform .25s ease, opacity .25s ease;
}
.menu-button.is-open span:nth-child(1) { transform: translateY(6px) rotate(45deg); }
.menu-button.is-open span:nth-child(2) { opacity: 0; }
.menu-button.is-open span:nth-child(3) { transform: translateY(-6px) rotate(-45deg); }
.mobile-menu {
  display: none;
  width: min(1180px, calc(100% - 32px));
  margin: 0 auto;
  padding: 0 0 18px;
  gap: 8px;
  flex-wrap: wrap;
}
.mobile-menu.is-open { display: flex; }

.curriculum-banner {
  background: var(--gold);
  color: var(--navy);
  text-align: center;
  font-weight: 900;
  letter-spacing: -.01em;
  padding: 12px 16px;
  box-shadow: inset 0 -1px rgba(10,10,35,.12);
}
.curriculum-banner:hover { text-decoration: underline; }

main { overflow: hidden; }
.section {
  width: min(1180px, calc(100% - 32px));
  margin: 0 auto;
  padding: 72px 0;
}
.section-tight { padding: 42px 0; }
.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--blue);
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: .09em;
  font-size: .77rem;
}
.eyebrow:before {
  content: "";
  width: 34px;
  height: 2px;
  background: var(--gold);
}
h1, h2, h3 { line-height: 1.02; letter-spacing: -.055em; margin: 0; }
h1 { font-size: clamp(3.2rem, 8vw, 7.8rem); }
h2 { font-size: clamp(2.1rem, 4vw, 4.2rem); }
h3 { font-size: clamp(1.2rem, 2vw, 1.75rem); }
p { margin: 0; color: var(--muted); }
.lede { font-size: clamp(1.08rem, 2vw, 1.35rem); max-width: 720px; }

.hero-grid {
  display: grid;
  grid-template-columns: 1.05fr .95fr;
  gap: 34px;
  align-items: stretch;
  padding-top: 58px;
}
.hero-copy {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: calc(var(--radius) + 8px);
  padding: clamp(28px, 5vw, 58px);
  box-shadow: var(--shadow);
}
.hero-copy h1 { margin: 18px 0 24px; }
.hero-note {
  margin-top: 32px;
  display: flex;
  gap: 14px;
  align-items: center;
  color: var(--muted);
  font-weight: 700;
}
.hero-note strong { color: var(--navy); }
.featured-card {
  position: relative;
  min-height: 540px;
  border-radius: calc(var(--radius) + 8px);
  overflow: hidden;
  color: white;
  background: var(--navy);
  box-shadow: var(--shadow);
  isolation: isolate;
}
.featured-card .thumb { position: absolute; inset: 0; }
.featured-card .thumb:after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(10,10,35,.08), rgba(10,10,35,.82));
}
.featured-card .article-art { height: 100%; border-radius: 0; }
.featured-content {
  position: absolute;
  inset: auto 0 0 0;
  padding: 34px;
  z-index: 1;
}
.featured-content h2 { font-size: clamp(2rem, 3.7vw, 4.5rem); margin: 18px 0 24px; }

.article-art {
  min-height: 220px;
  border-radius: 18px 18px 0 0;
  position: relative;
  overflow: hidden;
  background: var(--navy);
}
.article-art:before, .article-art:after {
  content: "";
  position: absolute;
  border-radius: 999px;
}
.article-art:before {
  width: 210px;
  height: 210px;
  right: -44px;
  top: -54px;
  background: rgba(254,172,50,.9);
}
.article-art:after {
  width: 175px;
  height: 175px;
  left: -38px;
  bottom: -52px;
  background: rgba(0,46,173,.72);
}
.article-art .grid-lines {
  position: absolute;
  inset: 0;
  background-image: linear-gradient(rgba(255,255,255,.16) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,.16) 1px, transparent 1px);
  background-size: 34px 34px;
  mask-image: linear-gradient(140deg, transparent, black 20%, black 80%, transparent);
}
.art-ai { background: radial-gradient(circle at 75% 20%, #feac32, transparent 34%), linear-gradient(135deg, #0a0a23, #26306a); }
.art-scrape { background: radial-gradient(circle at 28% 76%, #feac32, transparent 30%), linear-gradient(135deg, #09231e, #0f7b5f); }
.art-db { background: radial-gradient(circle at 72% 28%, #feac32, transparent 27%), linear-gradient(135deg, #24110b, #82421d); }
.art-search { background: radial-gradient(circle at 75% 25%, #feac32, transparent 28%), linear-gradient(135deg, #091f54, #002ead); }
.art-data { background: radial-gradient(circle at 72% 28%, #feac32, transparent 27%), linear-gradient(135deg, #0c272c, #208093); }
.art-code { background: radial-gradient(circle at 72% 28%, #feac32, transparent 27%), linear-gradient(135deg, #1c1838, #5f45a8); }

.section-head {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  align-items: end;
  margin-bottom: 28px;
}
.article-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 22px;
}
.article-card {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 22px;
  overflow: hidden;
  box-shadow: 0 12px 42px rgba(10,10,35,.06);
  transition: transform .25s ease, box-shadow .25s ease, border-color .25s ease;
}
.article-card:hover {
  transform: translateY(-6px);
  border-color: rgba(254,172,50,.7);
  box-shadow: 0 22px 70px rgba(10,10,35,.13);
}
.card-body { padding: 22px; }
.tag {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  background: var(--gold-soft);
  color: #7b4b00;
  border: 1px solid rgba(254,172,50,.42);
  padding: 6px 10px;
  font-size: .78rem;
  font-weight: 950;
  text-transform: uppercase;
  letter-spacing: .04em;
}
.article-card h3 { margin: 14px 0 18px; letter-spacing: -.035em; }
.meta {
  display: flex;
  align-items: center;
  gap: 11px;
  color: var(--muted);
  font-size: .92rem;
  font-weight: 680;
}
.avatar {
  width: 34px;
  height: 34px;
  border-radius: 999px;
  display: grid;
  place-items: center;
  background: var(--navy);
  color: var(--gold);
  font-size: .78rem;
  font-weight: 950;
  flex: 0 0 auto;
  box-shadow: inset 0 0 0 2px rgba(254,172,50,.25);
}
.meta-dot:before { content: "·"; margin: 0 4px; color: #9aa0af; }
.button-row { display: flex; justify-content: center; margin-top: 34px; }
.btn {
  display: inline-flex;
  justify-content: center;
  align-items: center;
  gap: 8px;
  min-height: 48px;
  padding: 0 20px;
  border: 0;
  border-radius: 999px;
  background: var(--navy);
  color: white;
  font-weight: 900;
  cursor: pointer;
  transition: transform .2s ease, background .2s ease, box-shadow .2s ease;
}
.btn:hover { transform: translateY(-2px); box-shadow: 0 16px 38px rgba(10,10,35,.20); }
.btn-gold { background: var(--gold); color: var(--navy); }
.btn-outline { background: white; color: var(--navy); border: 1px solid var(--line); }

.learn-hero, .donate-hero, .tag-hero {
  background: var(--paper);
  border-bottom: 1px solid var(--line);
}
.learn-hero .section, .donate-hero .section, .tag-hero .section { padding-top: 78px; padding-bottom: 78px; }
.split {
  display: grid;
  grid-template-columns: .95fr 1.05fr;
  gap: 36px;
  align-items: center;
}
.panel {
  background: white;
  border: 1px solid var(--line);
  border-radius: calc(var(--radius) + 6px);
  padding: clamp(24px, 4vw, 42px);
  box-shadow: var(--shadow);
}
.syllabus-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}
.cert-card, .resource-card, .stat-card, .benefit-card {
  background: white;
  border: 1px solid var(--line);
  border-radius: 20px;
  padding: 22px;
}
.cert-card {
  display: flex;
  gap: 15px;
  align-items: center;
  font-weight: 900;
}
.cert-icon {
  width: 44px;
  height: 44px;
  border-radius: 14px;
  background: var(--gold-soft);
  display: grid;
  place-items: center;
  color: #8a5300;
  font-size: 1.35rem;
  flex: 0 0 auto;
}
.resource-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 18px;
}
.resource-card h3 { margin-bottom: 14px; }
.resource-card ul, .clean-list {
  margin: 0;
  padding: 0;
  list-style: none;
}
.resource-card li, .clean-list li {
  padding: 10px 0;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-weight: 680;
}
.challenge-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  background: var(--navy);
  color: white;
  border-radius: calc(var(--radius) + 8px);
  padding: 34px;
  box-shadow: var(--shadow);
}
.challenge-card p { color: rgba(255,255,255,.72); }
.challenge-actions { display: flex; gap: 12px; flex-wrap: wrap; }

.donate-layout {
  display: grid;
  grid-template-columns: .95fr 1.05fr;
  gap: 28px;
  align-items: start;
}
.donation-card {
  background: white;
  border: 1px solid var(--line);
  border-radius: calc(var(--radius) + 8px);
  padding: clamp(24px, 4vw, 38px);
  box-shadow: var(--shadow);
}
.amount-tabs {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  margin: 20px 0;
}
.amount-tab {
  border: 1px solid var(--line);
  background: var(--wash);
  border-radius: 16px;
  padding: 14px 10px;
  font-weight: 950;
  cursor: pointer;
  color: var(--navy);
  transition: .2s ease;
}
.amount-tab.is-active {
  background: var(--gold);
  border-color: var(--gold);
  box-shadow: 0 12px 30px rgba(254,172,50,.35);
}
.donation-description {
  background: var(--gold-soft);
  border: 1px solid rgba(254,172,50,.45);
  color: #63400a;
  border-radius: 18px;
  padding: 16px;
  font-weight: 750;
  margin-bottom: 18px;
}
.donation-sub { margin-top: 14px; font-size: .92rem; text-align: center; }
.benefits-list li:before, .impact-list li:before {
  content: "";
  display: inline-block;
  width: 8px;
  height: 8px;
  margin-right: 10px;
  border-radius: 99px;
  background: var(--gold);
}
.impact-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 18px;
}
.faq-list { display: grid; gap: 10px; }
.faq-item {
  background: white;
  border: 1px solid var(--line);
  border-radius: 18px;
  overflow: hidden;
}
.faq-question {
  width: 100%;
  border: 0;
  background: transparent;
  text-align: left;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 20px 22px;
  color: var(--navy);
  font-weight: 900;
  cursor: pointer;
}
.faq-question:after {
  content: "+";
  width: 28px;
  height: 28px;
  border-radius: 999px;
  display: grid;
  place-items: center;
  background: var(--gold-soft);
  color: #7b4b00;
  flex: 0 0 auto;
}
.faq-item.is-open .faq-question:after { content: "–"; }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height .28s ease;
}
.faq-answer p { padding: 0 22px 20px; }
.faq-item.is-open .faq-answer { max-height: 180px; }

.tag-title-row {
  display: flex;
  justify-content: space-between;
  align-items: end;
  gap: 24px;
}
.post-count {
  color: var(--muted);
  font-size: 1.15rem;
  font-weight: 750;
}
.popular-tags {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  padding: 6px 2px 16px;
  scrollbar-width: thin;
}
.popular-tag {
  flex: 0 0 auto;
  background: white;
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 12px 16px;
  font-weight: 900;
  color: var(--navy);
  box-shadow: 0 8px 28px rgba(10,10,35,.05);
}
.popular-tag span { color: var(--muted); margin-left: 8px; font-weight: 750; }

.footer {
  background: var(--navy);
  color: white;
  margin-top: 48px;
}
.footer-inner {
  width: min(1180px, calc(100% - 32px));
  margin: 0 auto;
  padding: 54px 0;
  display: grid;
  grid-template-columns: 1.15fr .85fr;
  gap: 34px;
}
.footer p { color: rgba(255,255,255,.70); }
.footer h3 { font-size: 1rem; letter-spacing: 0; margin-bottom: 14px; }
.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.footer-links a {
  color: rgba(255,255,255,.75);
  border: 1px solid rgba(255,255,255,.14);
  border-radius: 999px;
  padding: 8px 10px;
  font-size: .9rem;
}
.footer-links a:hover { color: white; border-color: rgba(254,172,50,.8); }
.footer-stack { display: grid; gap: 28px; }

.reveal { animation: rise .55s ease both; }
@keyframes rise { from { opacity: 0; transform: translateY(18px); } to { opacity: 1; transform: translateY(0); } }

@media (max-width: 980px) {
  .header-inner { grid-template-columns: auto 1fr auto; gap: 14px; }
  .nav-links { display: none; }
  .menu-button { display: block; }
  .hero-grid, .split, .donate-layout, .footer-inner { grid-template-columns: 1fr; }
  .article-grid { grid-template-columns: repeat(2, 1fr); }
  .resource-grid { grid-template-columns: 1fr; }
  .challenge-card { align-items: flex-start; flex-direction: column; }
}
@media (max-width: 720px) {
  .header-inner { grid-template-columns: auto auto; justify-content: space-between; min-height: 64px; }
  .search-wrap { grid-column: 1 / -1; order: 3; padding-bottom: 14px; }
  .article-grid, .syllabus-grid, .impact-grid { grid-template-columns: 1fr; }
  .section { padding: 52px 0; }
  .hero-grid { padding-top: 34px; }
  .featured-card { min-height: 430px; }
  .section-head, .tag-title-row { align-items: flex-start; flex-direction: column; }
  .amount-tabs { grid-template-columns: repeat(2, 1fr); }
}
EOF

cat > /app/output/script.js <<'EOF'
const articles = [
  { tag: '#AI', title: 'Shadow AI Explained: Why Employees Are Using AI Behind Your Back', author: 'Manish Shivanandhan', time: '15 hours ago', art: 'art-ai' },
  { tag: '#web scraping', title: 'Traditional Scraping vs AI Scraping: A Practical Guide for Developers and Data Teams', author: 'Joel Olawanle', time: '16 hours ago', art: 'art-scrape' },
  { tag: '#Databases', title: 'How Database Indexes Work – A Practical Guide with PostgreSQL Examples', author: 'iyiola', time: '20 hours ago', art: 'art-db' },
  { tag: '#elasticsearch', title: 'How to Streamline Search in Web Applications with Elasticsearch', author: 'Oluwatobi', time: '21 hours ago', art: 'art-search' },
  { tag: '#data-engineering', title: 'How to Build an Open Source Data Lake for Batch Ingestion', author: 'Puneet Singh', time: 'a day ago', art: 'art-data' }
];

const moreArticles = [
  { tag: '#JavaScript', title: 'Build Accessible Components Without Losing Developer Velocity', author: 'OpenLearnHub Staff', time: '2 days ago', art: 'art-code' },
  { tag: '#Python', title: 'Python Automation Patterns Every Data Team Should Know', author: 'Amina Bello', time: '3 days ago', art: 'art-data' },
  { tag: '#React', title: 'State Management for Editorial Web Apps: A Practical Tour', author: 'Lee Robinson', time: '4 days ago', art: 'art-search' }
];

function initials(name) {
  if (!name || name === '—') return 'OL';
  return name.split(/\s+/).map(part => part[0]).join('').slice(0, 2).toUpperCase();
}

function articleCard(article) {
  const safeTitle = article.title.replace(/"/g, '&quot;');
  return `
    <article class="article-card reveal">
      <a href="#" aria-label="Read ${safeTitle}">
        <div class="article-art ${article.art || 'art-code'}"><span class="grid-lines"></span></div>
        <div class="card-body">
          <span class="tag">${article.tag}</span>
          <h3>${article.title}</h3>
          <div class="meta">
            <span class="avatar" aria-hidden="true">${initials(article.author)}</span>
            <span>${article.author || 'OpenLearnHub'}</span>
            <span class="meta-dot">${article.time}</span>
          </div>
        </div>
      </a>
    </article>`;
}

function setupMenus() {
  document.querySelectorAll('.menu-button').forEach(button => {
    button.addEventListener('click', () => {
      const target = document.getElementById(button.getAttribute('aria-controls'));
      const isOpen = target.classList.toggle('is-open');
      button.classList.toggle('is-open', isOpen);
      button.setAttribute('aria-expanded', String(isOpen));
    });
  });
}

function setupLoadMore() {
  const button = document.querySelector('[data-load-more]');
  const grid = document.querySelector('[data-article-grid]');
  if (!button || !grid) return;
  button.addEventListener('click', () => {
    grid.insertAdjacentHTML('beforeend', moreArticles.map(articleCard).join(''));
    button.textContent = 'More tutorials loaded';
    button.disabled = true;
  });
}

function setupDonations() {
  const tabs = document.querySelectorAll('[data-amount]');
  const description = document.querySelector('[data-donation-description]');
  const sublabel = document.querySelector('[data-donation-sub]');
  if (!tabs.length || !description || !sublabel) return;
  const messages = {
    5: 'Your $5 donation keeps lessons searchable, fast, and free for thousands of learners each month.',
    10: 'Your $10 donation helps publish practical tutorials and maintain learner support spaces each month.',
    20: 'Your $20 donation will provide 1,000 hours of learning to people around the world each month.',
    40: 'Your $40 donation funds new curriculum, translations, and open source improvements each month.'
  };
  tabs.forEach(tab => {
    tab.addEventListener('click', () => {
      const amount = tab.dataset.amount;
      tabs.forEach(item => item.classList.toggle('is-active', item === tab));
      description.textContent = messages[amount];
      sublabel.textContent = `Donating $${amount} / month: edit amount · Secure donation`;
    });
  });
}

function setupFaq() {
  document.querySelectorAll('.faq-question').forEach(question => {
    question.addEventListener('click', () => {
      const item = question.closest('.faq-item');
      const isOpen = item.classList.toggle('is-open');
      question.setAttribute('aria-expanded', String(isOpen));
    });
  });
}

document.addEventListener('DOMContentLoaded', () => {
  setupMenus();
  setupLoadMore();
  setupDonations();
  setupFaq();
});
EOF

