h1, h2, h3 { line-height: 1.02; letter-spacing: -.055em; margin: 0; }
h1 { font-size: clamp(3.2rem, 8vw, 7.8rem); }
h2 { font-size: clamp(2.1rem, 4vw, 4.2rem); }
h3 { font-size: clamp(1.2rem, 2vw, 1.75rem); }
p { margin: 0; color: var(--muted); }
