  box-shadow: var(--shadow);
  isolation: isolate;
}
.featured-card .thumb { position: absolute; inset: 0; }
.featured-card .thumb:after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(10,10,35,.08), rgba(10,10,35,.82));
}
.featured-card .article-art { height: 100%; border-radius: 0; }
.featured-content {
