.footer-links a:hover { color: white; border-color: rgba(254,172,50,.8); }
.footer-stack { display: grid; gap: 28px; }

.reveal { animation: rise .55s ease both; }
@keyframes rise { from { opacity: 0; transform: translateY(18px); } to { opacity: 1; transform: translateY(0); } }

@media (max-width: 980px) {
  .header-inner { grid-template-columns: auto 1fr auto; gap: 14px; }
  .nav-links { display: none; }
  .menu-button { display: block; }
  .hero-grid, .split, .donate-layout, .footer-inner { grid-template-columns: 1fr; }
  .article-grid { grid-template-columns: repeat(2, 1fr); }
